  "a2": "// Assignment 2: Operators, Expressions, and Input Handling\n\nconst billInput = prompt(\"Enter the bill amount ($):\", \"100\");\nconst tipInput = prompt(\"Enter the tip percentage (%):\", \"15\");\n\n// prompt() always gives us text, so convert it to numbers first\nconst subtotal = Number(billInput);\nconst tipPercent = Number(tipInput);\n\nif (isNaN(subtotal) || isNaN(tipPercent)) {\n  console.log(\"Please enter numbers only, for example 100 and 15.\");\n} else {\n  const tip = (subtotal * tipPercent) / 100;\n  let total = subtotal;\n  total += tip; // assignment operator at work\n\n  const money = (n) => \"$\" + Number(n.toFixed(2));\n\n  console.log(\"Subtotal: \" + money(subtotal));\n  console.log(\"Tip Percentage: \" + tipPercent + \"%\");\n  console.log(\"Calculated Tip: \" + money(tip));\n  console.log(\"Total Amount to Pay: \" + money(total));\n}\n",
  "a3": "// Assignment 3: Conditional Logic Implementation\n\nconst score = Number(prompt(\"Enter your test score (0-100):\", \"85\"));\n\nif (isNaN(score) || score < 0 || score > 100) {\n  console.log(\"Invalid score. Please enter a number between 0 and 100.\");\n} else {\n  let grade;\n\n  // switch decides the letter grade (score / 10 gives us the tens digit)\n  switch (Math.floor(score / 10)) {\n    case 10:\n    case 9:\n      grade = \"A\";\n      break;\n    case 8:\n      grade = \"B\";\n      break;\n    case 7:\n      grade = \"C\";\n      break;\n    case 6:\n    case 5:\n      grade = \"D\";\n      break;\n    default:\n      grade = \"F\";\n  }\n\n  // ternary operator decides pass or fail (pass mark is 50)\n  const status = score >= 50 ? \"Passed\" : \"Failed\";\n\n  console.log(\"Score: \" + score);\n  console.log(\"Grade: \" + grade);\n  console.log(\"Status: \" + status);\n}\n",
  "a4": "// Assignment 4: Loop Control Structures\n\n// 1) for loop: multiplication table of 5\nconsole.log(\"-- Multiplication Table of 5 --\");\nfor (let i = 1; i <= 5; i++) {\n  console.log(\"5 x \" + i + \" = \" + 5 * i);\n}\n\n// 2) while loop + break: first number greater than 10 divisible by 6\nconsole.log(\"-- First number > 10 divisible by 6 --\");\nlet n = 11;\nwhile (true) {\n  if (n % 6 === 0) {\n    console.log(\"Found: \" + n);\n    break;\n  }\n  n++;\n}\n\n// 3) do...while + continue: count from 1 to 6 but skip multiples of 3\nconsole.log(\"-- do...while skipping multiples of 3 --\");\nlet k = 0;\ndo {\n  k++;\n  if (k % 3 === 0) {\n    continue;\n  }\n  console.log(\"Number: \" + k);\n} while (k < 6);\n",
  "a5": "// Assignment 5: Function Architecture and Scope\n\n// Standard function with default parameter values\nfunction areaStandard(length = 5, width = 4) {\n  return length * width;\n}\n\n// Arrow function with default parameter values\nconst areaArrow = (length = 5, width = 4) => length * width;\n\nconsole.log(\"Standard Function Area (Default 5x4): \" + areaStandard());\nconsole.log(\"Arrow Function Area (Custom 10x3): \" + areaArrow(10, 3));\n\n// Scope demo: block scope\n{\n  let blockVar = \"I only exist inside this block\";\n  var leakyVar = \"var ignores block scope\";\n}\n\ntry {\n  console.log(blockVar);\n} catch (error) {\n  console.log(\"Scope Test Error: \" + error.name + \": \" + error.message + \" (when accessed outside block)\");\n}\n\n// Scope demo: function scope\nfunction makeSecret() {\n  const secret = \"I only exist inside makeSecret()\";\n  return secret.length;\n}\nmakeSecret();\n\ntry {\n  console.log(secret);\n} catch (error) {\n  console.log(\"Function Scope Error: \" + error.name + \": \" + error.message + \" (when accessed outside function)\");\n}\n",
